17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.ArrayList;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.Map;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.util.StringUtils;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    /**
77	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
78	     * and a domain containing at least one dot, with no whitespace in any segment.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
84	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
85	     */
86	    private static final int MAX_OWNERS_PER_CITY = 50;
87	
88	    /**
89	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
90	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
91	     */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
93	        "ST", "STREET",
94	        "RD", "ROAD",
95	        "AVE", "AVENUE");
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        validateRequiredFields(ownerFieldsDto);
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        requireCityHasCapacity(owner.getCity());
139	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
140	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
141	            joinHousehold(owner);
142	        } else {
143	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
144	        }
145	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
146	        requireUniqueTelephone(telephone);
147	        owner.setTelephone(telephone);
148	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
149	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
150	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
151	        this.clinicService.saveOwner(owner);
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    /**
159	     * Rejects an owner whose city already contains the maximum allowed number of owners
160	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
161	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
162	     * create.
163	     *
164	     * @param city the city of the owner being created
165	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
166	     */
167	    private void requireCityHasCapacity(String city) {
168	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
170	            .count();
171	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
172	            throw new CityOwnerLimitException(city);
173	        }
174	    }
175	
176	    /**
177	     * Generates the customer code for a newly created owner, formatted
178	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
179	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
180	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
181	     * that city (e.g. {@code 'LON-SMI-0007'}).
182	     *
183	     * @param city the owner's city
184	     * @param lastName the owner's last name
185	     * @return the generated customer code
186	     */
187	    private String generateCustomerCode(String city, String lastName) {
188	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
189	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
190	        int sequence = (int) this.clinicService.findAllOwners().stream()
191	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
192	            .count() + 1;
193	        return String.format("%s-%s-%04d", city3, last3, sequence);
194	    }
195	
196	    /**
197	     * Counts the existing owners that already share the given first name and last name, compared
198	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
199	     * owners that existed prior to this create.
200	     *
201	     * @param firstName the first name of the owner being created
202	     * @param lastName the last name of the owner being created
203	     * @return the number of pre-existing namesakes
204	     */
205	    private int countNamesakes(String firstName, String lastName) {
206	        return (int) this.clinicService.findAllOwners().stream()
207	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
208	                && equalsIgnoreCase(existing.getLastName(), lastName))
209	            .count();
210	    }
211	
212	    /**
213	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
214	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
215	     *
216	     * @param a the first value, possibly {@code null}
217	     * @param b the second value, possibly {@code null}
218	     * @return whether the values are equal ignoring case
219	     */
220	    private boolean equalsIgnoreCase(String a, String b) {
221	        return a == null ? b == null : a.equalsIgnoreCase(b);
222	    }
223	
224	    /**
225	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
226	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
227	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
228	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
229	     *
230	     * @param ownerFieldsDto the submitted owner fields
231	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
232	     */
233	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
234	        List<String> invalidFields = new ArrayList<>();
235	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
236	            invalidFields.add("firstName");
237	        }
238	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
239	            invalidFields.add("lastName");
240	        }
241	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
242	            invalidFields.add("address");
243	        }
244	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
245	            invalidFields.add("city");
246	        }
247	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
248	            invalidFields.add("telephone");
249	        }
250	        if (!invalidFields.isEmpty()) {
251	            throw new InvalidOwnerFieldsException(invalidFields);
252	        }
253	    }
254	
255	    /**
256	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
257	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
258	     * what gets stored and returned.
259	     *
260	     * @param telephone the raw telephone value from the request
261	     * @return the normalized E.164 telephone number
262	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
263	     */
264	    private String normalizeTelephone(String telephone) {
265	        String e164 = toE164(telephone);
266	        if (e164 == null) {
267	            throw new InvalidOwnerFieldsException(List.of("telephone"));
268	        }
269	        return e164;
270	    }
271	
272	    /**
273	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
274	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
275	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
276	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
277	     * it contains 8 to 15 digits after the {@code '+'}.
278	     *
279	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
280	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
281	     *
282	     * @param telephone the raw telephone value, possibly {@code null}
283	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
284	     */
285	    private String toE164(String telephone) {
286	        if (telephone == null) {
287	            return null;
288	        }
289	        String cleaned = telephone.replaceAll("[ \\-()]", "");
290	        String digits;
291	        if (cleaned.startsWith("+")) {
292	            digits = cleaned.substring(1);
293	        } else {
294	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
295	            digits = "61" + national;
296	        }
297	        if (!digits.matches("[0-9]{8,15}")) {
298	            return null;
299	        }
300	        return "+" + digits;
301	    }
302	
303	    /**
304	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
305	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
306	     * and returned lower-cased.
307	     *
308	     * @param email the raw email value from the request, possibly {@code null}
309	     * @return the lower-cased email, or {@code null} when none was supplied
310	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
311	     */
312	    private String normalizeEmail(String email) {
313	        if (!StringUtils.hasText(email)) {
314	            return null;
315	        }
316	        String trimmed = email.trim();
317	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
318	            throw new InvalidOwnerFieldsException(List.of("email"));
319	        }
320	        return trimmed.toLowerCase(Locale.ROOT);
321	    }
322	
323	    /**
324	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
325	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
326	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
327	     *
328	     * @param telephone the normalized (E.164) telephone of the owner being created
329	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
330	     */
331	    private void requireUniqueTelephone(String telephone) {
332	        boolean inUse = this.clinicService.findAllOwners().stream()
333	            .map(Owner::getTelephone)
334	            .filter(existing -> existing != null)
335	            .map(existing -> {
336	                String e164 = toE164(existing);
337	                return e164 != null ? e164 : existing;
338	            })
339	            .anyMatch(telephone::equals);
340	        if (inUse) {
341	            throw new DuplicateTelephoneException(telephone);
342	        }
343	    }
344	
345	    /**
346	     * Rejects an owner whose last name and address match those of an existing owner, where both are
347	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
348	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
349	     *
350	     * @param lastName the last name of the owner being created
351	     * @param address the address of the owner being created
352	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
353	     */
354	    private void requireUniqueHousehold(String lastName, String address) {
355	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
356	            throw new DuplicateHouseholdException(lastName, address);
357	        }
358	    }
359	
360	    /**
361	     * Returns the existing owners that belong to the same household as the given last name and
362	     * address, i.e. those whose last name and address match case-insensitively and with runs of
363	     * whitespace collapsed to a single space.
364	     *
365	     * @param lastName the last name to match
366	     * @param address the address to match
367	     * @return the matching owners (possibly empty, never {@code null})
368	     */
369	    private List<Owner> findHouseholdMembers(String lastName, String address) {
370	        String normalizedLastName = normalizeForHousehold(lastName);
371	        String normalizedAddress = normalizeAddress(address);
372	        return this.clinicService.findAllOwners().stream()
373	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
374	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
375	            .toList();
376	    }
377	
378	    /**
379	     * Joins the owner being created to the shared household of any existing owner(s) that have the
380	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
381	     * member of the household - the existing owners and the new one - is assigned the same stable
382	     * {@code householdId}, so the shared identifier can be read back from any of them.
383	     *
384	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
385	     * the owner is left without a {@code householdId}.
386	     *
387	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
388	     */
389	    private void joinHousehold(Owner owner) {
390	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
391	        if (members.isEmpty()) {
392	            return;
393	        }
394	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
395	        owner.setHouseholdId(householdId);
396	        for (Owner member : members) {
397	            if (!householdId.equals(member.getHouseholdId())) {
398	                member.setHouseholdId(householdId);
399	                this.clinicService.saveOwner(member);
400	            }
401	        }
402	    }
403	
404	    /**
405	     * Computes the stable, shared household identifier for a last name and address. The value is
406	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
407	     * name and address, so every owner in the same household computes the same identifier.
408	     *
409	     * @param lastName the last name of the household
410	     * @param address the address of the household
411	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
412	     */
413	    private String computeHouseholdId(String lastName, String address) {
414	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
415	        try {
416	            byte[] digest = MessageDigest.getInstance("SHA-256")
417	                .digest(key.getBytes(StandardCharsets.UTF_8));
418	            StringBuilder hex = new StringBuilder();
419	            for (int i = 0; i < 6; i++) {
420	                hex.append(String.format("%02X", digest[i]));
421	            }
422	            return "HH-" + hex;
423	        } catch (NoSuchAlgorithmException e) {
424	            throw new IllegalStateException("SHA-256 algorithm not available", e);
425	        }
426	    }
427	
428	    /**
429	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
430	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
431	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
432	     *
433	     * @param value the raw value, possibly {@code null}
434	     * @return the normalized value
435	     */
436	    private String normalizeForHousehold(String value) {
437	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
438	    }
439	
440	    /**
441	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
442	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
443	     * value yields an empty string.
444	     *
445	     * @param value the raw value, possibly {@code null}
446	     * @return the trimmed, whitespace-collapsed value
447	     */
448	    private String collapseWhitespace(String value) {
449	        if (value == null) {
450	            return "";
451	        }
452	        return value.trim().replaceAll("\\s+", " ");
453	    }
454	
455	    /**
456	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
457	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
458	     * is upper-cased, and common street-type abbreviations are expanded as whole words
459	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
460	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
461	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
462	     *
463	     * @param address the raw address value, possibly {@code null}
464	     * @return the normalized address
465	     */
466	    private String normalizeAddress(String address) {
467	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
468	        if (collapsed.isEmpty()) {
469	            return "";
470	        }
471	        String[] tokens = collapsed.split(" ");
472	        StringBuilder normalized = new StringBuilder();
473	        for (int i = 0; i < tokens.length; i++) {
474	            if (i > 0) {
475	                normalized.append(' ');
476	            }
477	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
478	        }
479	        return normalized.toString();
480	    }
481	
482	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
483	    @Override
484	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
485	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
486	        if (currentOwner == null) {
487	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
488	        }
489	        currentOwner.setAddress(ownerFieldsDto.getAddress());
490	        currentOwner.setCity(ownerFieldsDto.getCity());
491	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
492	        currentOwner.setLastName(ownerFieldsDto.getLastName());
493	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
494	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
495	        this.clinicService.saveOwner(currentOwner);
496	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Transactional
501	    @Override
502	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
503	        Owner owner = this.clinicService.findOwnerById(ownerId);
504	        if (owner == null) {
505	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	        }
507	        this.clinicService.deleteOwner(owner);
508	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
509	    }
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
514	        Owner owner = this.clinicService.findOwnerById(ownerId);
515	        if (owner == null) {
516	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
517	        }
518	        HttpHeaders headers = new HttpHeaders();
519	        Pet pet = petMapper.toPet(petFieldsDto);
520	        owner.setId(ownerId);
521	        pet.setOwner(owner);
522	        pet.getType().setName(null);
523	        this.clinicService.savePet(pet);
524	        PetDto petDto = petMapper.toPetDto(pet);
525	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
526	            .buildAndExpand(pet.getId()).toUri());
527	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
528	    }
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Override
532	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
533	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
534	        if (currentOwner != null) {
535	            Pet currentPet = this.clinicService.findPetById(petId);
536	            if (currentPet != null) {
537	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
538	                currentPet.setName(petFieldsDto.getName());
539	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
540	                this.clinicService.savePet(currentPet);
541	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
542	            }
543	        }
544	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
545	    }
