548	    @Override
549	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
550	        HttpHeaders headers = new HttpHeaders();
551	        Visit visit = visitMapper.toVisit(visitFieldsDto);
552	        Pet pet = new Pet();
553	        pet.setId(petId);
